const Step = struct { name: []const u8, reads: []const []const u8, writes: []const []const u8 };

/// Drafter.attention's launch order as each arm runs it (draft.zig's calls), as buffers: every read must follow/// that buffer's write. The attention partials and weights are inputs; x is written by the mix before it.
fn armSteps(joint: bool, lora: bool) []const Step {
    var steps: [8]Step = undefined;
    var n: usize = 0;
    steps[n] = .{ .name = "attn_in", .reads = &.{"x"}, .writes = &.{ "qa", "ykv" } }; n += 1;
    if (lora) {
        steps[n] = .{ .name = "lora_qa", .reads = &.{"x"}, .writes = &.{"qa"} }; n += 1;
